CREATE OR REPLACE FUNCTION mission_factory_owner.c352_native_resource_source_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE arenas jsonb;g record;n record;fixed jsonb;
BEGIN
 IF md5((SELECT prosrc FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('combat_spatial.template_errors(text,integer)'))) IS DISTINCT FROM '168b5e4047516083612b098bbdb02d53' OR md5((SELECT prosrc FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('combat_spatial.geometry_fingerprint(text,integer)'))) IS DISTINCT FROM '0de21ad0c82fcaa9837258760ea8b539' OR md5((SELECT prosrc FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('mission_factory_owner.quest_reward_fixed30_document_v2()'))) IS DISTINCT FROM '11495ff3601204655f52da6219753675' OR md5((SELECT prosrc FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('mission_factory_owner.quest_reward_policy_checked_v2(uuid)'))) IS DISTINCT FROM '7280f298d37324a1b655d561081dd6bd' THEN RAISE EXCEPTION 'C352_CURRENT_NATIVE_PRODUCER_BODY_DRIFT';END IF;
 SELECT mode,provider_max_calls,provider_max_cost_usd INTO STRICT g FROM mission_generic_owner.runtime_policy WHERE singleton;
 SELECT policy_version,model,reasoning_effort,store,max_input_tokens,max_output_tokens,input_usd_million,output_usd_million INTO STRICT n FROM mission_narrative_internal.runtime_policy WHERE singleton;
 IF g.mode IS DISTINCT FROM 'all' OR g.provider_max_calls IS DISTINCT FROM 14 OR g.provider_max_cost_usd IS DISTINCT FROM .156688 OR n.policy_version IS DISTINCT FROM 2 OR n.model IS DISTINCT FROM 'gpt-6-luna' OR n.reasoning_effort IS DISTINCT FROM 'high' OR n.store IS DISTINCT FROM false OR n.max_input_tokens IS DISTINCT FROM 12000 OR n.max_output_tokens IS DISTINCT FROM 20000 OR n.input_usd_million IS DISTINCT FROM .1 OR n.output_usd_million IS DISTINCT FROM .5 THEN RAISE EXCEPTION 'C352_APPROVED_NATIVE_NUMERIC_POLICY_DRIFT';END IF;
 fixed:=mission_factory_owner.quest_reward_fixed30_document_v2();
 IF fixed IS DISTINCT FROM '{"schema_version":"mission-factory-quest-reward-policy/2","recipient_mode":"uniform","xp_per_eligible_recipient":30,"ryo_per_eligible_recipient":0,"items":[],"terminal_outcomes":["success","failure"],"award_scope":"arc_once_per_character"}'::jsonb THEN RAISE EXCEPTION 'C352_APPROVED_FIXED30_DOCUMENT_DRIFT';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('template_key',t.template_key,'template_version',t.template_version,'contract_version',t.contract_version,'geometry_contract_id',t.geometry_contract_id,'geometry_contract_version',t.geometry_contract_version,'source_asset_sha256',t.source_asset_sha256,'geometry_hash',t.geometry_hash,'status',t.status,'errors',combat_spatial.template_errors(t.template_key,t.template_version),'fingerprint',combat_spatial.geometry_fingerprint(t.template_key,t.template_version)) ORDER BY t.template_key,t.template_version),'[]'::jsonb) INTO arenas FROM combat_spatial.arena_templates t WHERE t.status='ready';
 RETURN jsonb_build_object('schema_version','mission-factory-native-resource-source/1','arenas',arenas,'generic_policy',to_jsonb(g),'narrative_policy',to_jsonb(n),'fixed30_document',fixed,'fixed30_document_sha256',mission_factory_owner.sha(fixed),'budget_limits',jsonb_build_object('max_calls',g.provider_max_calls,'max_input_tokens',n.max_input_tokens,'max_output_tokens',n.max_output_tokens,'max_cost_usd',g.provider_max_cost_usd),'Count',jsonb_build_object('state','UNKNOWN','rate',null,'qualified',false),'producer_versions',jsonb_build_object('template_errors_md5','168b5e4047516083612b098bbdb02d53','geometry_fingerprint_md5','0de21ad0c82fcaa9837258760ea8b539','fixed30_document_md5','11495ff3601204655f52da6219753675','fixed30_checked_md5','7280f298d37324a1b655d561081dd6bd'));
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c352_prepare_resource_v1(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE actor uuid;request uuid;source jsonb;srcsha text;actual jsonb;before_budget jsonb;before_selection jsonb;old mission_factory_owner.c352_resource_requests;maps jsonb;budget_id uuid;reward_id uuid;budget_doc jsonb;reward_doc jsonb;doc jsonb;ident uuid;fp text;result jsonb;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres' OR p IS NULL OR NOT mission_factory_owner.keys_exact_v2(p,ARRAY['schema_version','operation','source_R','review_ref','review_sha256','review_findings','authorization_ref','authority_evidence_sha256','baseline_evidence_sha256','native_source_sha256','rows_before','actor_user','request_key']) OR p->>'schema_version' IS DISTINCT FROM 'c352-root-resource-authority/1' OR p->>'operation' IS DISTINCT FROM 'prepare_source_qualified_resources' OR p->>'source_R' IS DISTINCT FROM 'fbb35e4382ab54b2f2fdfd8d5fe2300afb664a416724f43096dfc7491ccc09f2' OR p->'review_findings' IS DISTINCT FROM '{"P0":0,"P1":0,"P2":0}'::jsonb OR EXISTS(SELECT 1 FROM jsonb_each(p) x WHERE x.key IN('review_sha256','authority_evidence_sha256','baseline_evidence_sha256','native_source_sha256') AND (jsonb_typeof(x.value) IS DISTINCT FROM 'string' OR x.value#>>'{}'!~'^[0-9a-f]{64}$')) OR EXISTS(SELECT 1 FROM jsonb_each_text(p) x WHERE x.key IN('review_ref','authorization_ref') AND (x.value IS NULL OR octet_length(x.value)>256 OR x.value!~'^[A-Za-z0-9_./:#-]+$')) OR jsonb_typeof(p->'rows_before') IS DISTINCT FROM 'object' OR NOT mission_factory_owner.keys_exact_v2(p->'rows_before',ARRAY['budget_selection','resource_selection','budget_versions','reward_versions']) THEN RAISE EXCEPTION 'C352_GENUINE_CLOSED_ROOT_REVIEW_REQUIRED';END IF;
 actor:=(p->>'actor_user')::uuid;request:=(p->>'request_key')::uuid;
 IF actor IS NULL OR request IS NULL OR actor NOT IN('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid) OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor AND role IN('admin','master')) THEN RAISE EXCEPTION 'C352_REAL_STAFF_SOURCE_ATTRIBUTION_REQUIRED';END IF;
 fp:=mission_factory_owner.sha(p-ARRAY['rows_before']::text[]);
 PERFORM pg_advisory_xact_lock(hashtextextended('c352-resource',352));
 SELECT * INTO old FROM mission_factory_owner.c352_resource_requests WHERE request_key=request;
 IF FOUND THEN IF old.actor_user IS DISTINCT FROM actor OR old.request_fingerprint IS DISTINCT FROM fp THEN RAISE EXCEPTION 'C352_REQUEST_REPLAY_CONFLICT' USING ERRCODE='40001';END IF;RETURN old.receipt;END IF;
 LOCK TABLE combat_spatial.arena_templates,mission_generic_owner.runtime_policy,mission_narrative_internal.runtime_policy IN SHARE MODE;
 LOCK TABLE mission_factory_owner.budget_policy_selection,mission_factory_owner.budget_policy_versions,mission_factory_owner.quest_reward_policy_versions,mission_factory_owner.c352_resource_selection IN SHARE ROW EXCLUSIVE MODE;
 SELECT to_jsonb(x) INTO before_budget FROM mission_factory_owner.budget_policy_selection x WHERE singleton;
 SELECT to_jsonb(x) INTO before_selection FROM mission_factory_owner.c352_resource_selection x WHERE singleton;
 IF before_budget IS NULL OR before_budget IS DISTINCT FROM p->'rows_before'->'budget_selection' OR coalesce(before_selection,'null'::jsonb) IS DISTINCT FROM p->'rows_before'->'resource_selection' THEN RAISE EXCEPTION 'C352_SELECTION_FULL_RAW_CAS';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]'::jsonb) INTO actual FROM mission_factory_owner.budget_policy_versions x;IF actual IS DISTINCT FROM p->'rows_before'->'budget_versions' THEN RAISE EXCEPTION 'C352_BUDGET_VERSIONS_CAS';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]'::jsonb) INTO actual FROM mission_factory_owner.quest_reward_policy_versions x;IF actual IS DISTINCT FROM p->'rows_before'->'reward_versions' THEN RAISE EXCEPTION 'C352_REWARD_VERSIONS_CAS';END IF;
 IF EXISTS(SELECT 1 FROM mission_factory_owner.manual_authoring_admissions_v1 WHERE enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.provider_authoring_runtime WHERE enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.provider_authoring_admissions WHERE enabled) OR EXISTS(SELECT 1 FROM mission_public_owner.public_authoring_gate_v1 WHERE enabled OR provider_enabled) OR EXISTS(SELECT 1 FROM mission_public_owner.release_admissions_v1 WHERE public_enabled) OR EXISTS(SELECT 1 FROM mission_public_owner.existing_publication_gate_v1 WHERE enabled) OR EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND closed_at IS NULL) OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND closed_at IS NULL) OR EXISTS(SELECT 1 FROM public.academy_class_sessions WHERE location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND closed_at IS NULL) THEN RAISE EXCEPTION 'C352_OWN_CFG_CLOSED_QUIESCENT_REQUIRED';END IF;
 source:=mission_factory_owner.c352_native_resource_source_v1();srcsha:=mission_factory_owner.sha(source);
 IF srcsha IS DISTINCT FROM p->>'native_source_sha256' THEN RAISE EXCEPTION 'C352_FRESH_NATIVE_RESOURCE_CAS' USING ERRCODE='40001';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('schema_version','map-reference/1','template_key',a->>'template_key','template_version',(a->>'template_version')::integer,'geometry_hash',a->>'geometry_hash','source_asset_sha256',a->>'source_asset_sha256','contract_version',a->>'contract_version','geometry_contract_id',a->>'geometry_contract_id','geometry_contract_version',(a->>'geometry_contract_version')::integer,'zone_keys',jsonb_build_array('arena'),'allowed_content_kinds',jsonb_build_array('mission','quest_ai'),'ready',true,'qualified',true,'qualification_kind','native_geometry_schema_authority','reason_code',null) ORDER BY a->>'template_key',(a->>'template_version')::integer),'[]'::jsonb) INTO maps FROM jsonb_array_elements(source->'arenas') a WHERE a->>'status'='ready' AND a->'errors'='[]'::jsonb AND a->>'geometry_hash'=a->>'fingerprint';
 IF jsonb_array_length(maps)=0 THEN RAISE EXCEPTION 'C352_NO_NATIVE_READY_MAPS';END IF;
 budget_doc:=source->'budget_limits';reward_doc:=source->'fixed30_document';
 SELECT id INTO budget_id FROM mission_factory_owner.budget_policy_versions WHERE limits=budget_doc AND limits_sha256=mission_factory_owner.sha(limits) ORDER BY created_at,id LIMIT 1;
 IF budget_id IS NULL THEN INSERT INTO mission_factory_owner.budget_policy_versions(limits,limits_sha256,created_by) VALUES(budget_doc,mission_factory_owner.sha(budget_doc),actor) RETURNING id INTO budget_id;END IF;
 SELECT id INTO reward_id FROM mission_factory_owner.quest_reward_policy_versions WHERE document=reward_doc AND document_sha256=mission_factory_owner.sha(document) AND qualified AND scope='staff' ORDER BY created_at,id LIMIT 1;
 IF reward_id IS NULL THEN INSERT INTO mission_factory_owner.quest_reward_policy_versions(document,document_sha256,qualified,scope,created_by) VALUES(reward_doc,mission_factory_owner.sha(reward_doc),true,'staff',actor) RETURNING id INTO reward_id;END IF;
 -- qualified means exact approved fixed30 schema/source authority. It does not enable award admission.
 PERFORM mission_factory_owner.quest_reward_policy_checked_v2(reward_id);
 doc:=jsonb_build_object('schema_version','mission-factory-resource-snapshot/1','map_references',maps,'budget_policies',jsonb_build_array(jsonb_build_object('id',budget_id,'label','Policy IA server approvata','allowed_content_kinds',jsonb_build_array('mission','quest_ai'),'qualified',true,'qualification_kind','approved_numeric_server_policy','limits',budget_doc)),'reward_policies',jsonb_build_array(jsonb_build_object('id',reward_id,'label','30 XP per PG · 0 Ryō · nessun oggetto','allowed_content_kinds',jsonb_build_array('quest_ai'),'qualified',true,'qualification_kind','fixed30_schema_source_authority','policy_sha256',mission_factory_owner.sha(reward_doc),'document',reward_doc,'scope','staff')),'limits',jsonb_build_object('provider',budget_doc,'team_min',1,'team_max',4,'Count',source->'Count'),'media_binding_source','public.mission_factory_context_media_catalog_v2(uuid,text)','source_sha256',srcsha,'gameplay_qualified',false,'provider_public_enabled',false);
 INSERT INTO mission_factory_owner.c352_resource_versions(source_snapshot,source_sha256,document,document_sha256,budget_policy_id,reward_policy_id,review_ref,review_sha256,authorization_ref,created_by) VALUES(source,srcsha,doc,mission_factory_owner.sha(doc),budget_id,reward_id,p->>'review_ref',p->>'review_sha256',p->>'authorization_ref',actor) RETURNING id INTO ident;
 UPDATE mission_factory_owner.budget_policy_selection SET active_policy_id=budget_id,control_version=control_version+1,updated_at=statement_timestamp() WHERE singleton;
 INSERT INTO mission_factory_owner.c352_resource_selection(singleton,resource_version_id,enabled,control_version) VALUES(true,ident,true,1) ON CONFLICT(singleton) DO UPDATE SET resource_version_id=excluded.resource_version_id,enabled=true,control_version=c352_resource_selection.control_version+1,updated_at=statement_timestamp();
 result:=jsonb_build_object('schema_version','c352-resource-preparation-receipt/1','request_key',request,'resource_version_id',ident,'resource_sha256',mission_factory_owner.sha(doc),'native_source_sha256',srcsha,'budget_policy_id',budget_id,'reward_policy_id',reward_id,'map_count',jsonb_array_length(maps),'qualification','resources_schema_source_only_not_gameplay','runtime_provider_public',false);
 INSERT INTO mission_factory_owner.c352_resource_requests(request_key,actor_user,request_fingerprint,resource_version_id,budget_before,selection_before,receipt) VALUES(request,actor,fp,ident,before_budget,before_selection,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c353_after_d100_v1(p_location uuid, p_character uuid, p_message uuid, p_result integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q mission_factory_owner.quest_run_sources; r public.mission_run_state;
 b mission_factory_owner.c353_d100_bindings; old mission_factory_owner.c353_d100_receipts;
 guide mission_factory_owner.c353_d100_rolls; support mission_factory_owner.c353_d100_rolls;
 ch mission_academy_owner.d100_challenges; policy mission_academy_owner.policies;
 receipt_id uuid; role_name text; snapshot jsonb; phase jsonb; facts jsonb; threshold integer; ok boolean; fact text; decision text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c353_d100_control WHERE singleton AND enabled)
 THEN RETURN NULL;END IF;
 SELECT qs.* INTO q FROM mission_factory_owner.quest_run_sources qs
  JOIN public.master_v2_sessions ms ON ms.id=qs.session_id AND ms.stato='in_corso' AND ms.closed_at IS NULL
  JOIN public.master_v2_participants mp ON mp.session_id=ms.id AND mp.character_id=p_character
   AND mp.left_at IS NULL AND mp.engagement_state='attivo'
  WHERE qs.location_id=p_location AND p_location='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND qs.state='started';
 IF q.session_id IS NULL THEN RETURN NULL;END IF;
 PERFORM public.master_v2_lock_scope(q.session_id);
 PERFORM mission_factory_owner.quest_run_source_assert_v1(q.session_id);
 IF mission_factory_owner.quest_is_simulation_v4(q.arc_id) IS DISTINCT FROM true
  OR auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.characters c WHERE c.id=p_character AND c.user_id=auth.uid())
  OR NOT EXISTS(SELECT 1 FROM public.messages msg WHERE msg.id=p_message AND msg.location_id=p_location
   AND msg.character_id=p_character AND msg.sender_user=auth.uid() AND msg.kind='roll'
   AND msg.dice_sides=100 AND msg.dice_result=p_result AND msg.recipient_user IS NULL)
 THEN RAISE EXCEPTION 'C353_D100_SCOPE' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=q.session_id FOR UPDATE;
 SELECT value INTO phase FROM mission_factory_owner.quest_episodes e,
  LATERAL jsonb_array_elements(e.source_document->'phases') WHERE e.id=q.episode_id
   AND value->>'step_key'=r.current_step_key;
 IF phase IS NULL OR phase->>'capability_key' IS DISTINCT FROM 'd100.native' THEN RETURN NULL;END IF;
 IF r.run_phase<>'in_corso' OR r.source_kind<>'quest' OR EXISTS(SELECT 1 FROM public.mission_run_outbox o
  WHERE o.master_session_id=q.session_id AND o.event_version_after=r.control_version AND o.step_key=r.current_step_key
   AND o.state IN('pending','human_directed'))
 THEN RAISE EXCEPTION 'C353_D100_FATO_PENDING' USING ERRCODE='55000';END IF;
 SELECT * INTO b FROM mission_factory_owner.c353_d100_bindings WHERE session_id=q.session_id
  AND step_key=r.current_step_key AND run_control_version=r.control_version FOR SHARE;
 IF b.id IS NULL THEN RAISE EXCEPTION 'C353_D100_BINDING_REQUIRED' USING ERRCODE='55000';END IF;
 IF b.quest_source_sha256<>q.source_sha256 OR b.plan_version_id<>q.plan_version_id OR b.definition_sha256<>q.definition_sha256
  OR b.roster_character_ids IS DISTINCT FROM q.roster_character_ids OR b.phase_sha256<>mission_factory_owner.sha(phase)
  OR EXISTS(SELECT 1 FROM unnest(b.roster_character_ids) x WHERE NOT EXISTS(SELECT 1 FROM public.master_v2_participants mp
   WHERE mp.session_id=q.session_id AND mp.character_id=x AND mp.left_at IS NULL AND mp.engagement_state='attivo'))
 THEN RAISE EXCEPTION 'C353_D100_BINDING_DRIFT' USING ERRCODE='40001';END IF;
 SELECT * INTO STRICT policy FROM mission_academy_owner.policies WHERE mission_id=b.policy_mission_id AND active FOR SHARE;
 SELECT * INTO STRICT ch FROM mission_academy_owner.d100_challenges
  WHERE mission_id=b.policy_mission_id AND step_key=b.policy_step_key AND active FOR SHARE;
 snapshot:=jsonb_build_object('policy',to_jsonb(policy),'challenge',to_jsonb(ch));
 IF b.native_policy_sha256<>mission_factory_owner.sha(snapshot)
 THEN RAISE EXCEPTION 'C353_D100_NATIVE_POLICY_DRIFT' USING ERRCODE='40001';END IF;
 role_name:=CASE WHEN p_character=b.guide_character_id THEN 'guide'
  WHEN p_character=b.support_character_id THEN 'support' ELSE NULL END;
 IF role_name IS NULL THEN RETURN jsonb_build_object('schema_version','quest-d100-progress/1','state','role_not_required','binding_id',b.id);END IF;
 SELECT * INTO old FROM mission_factory_owner.c353_d100_receipts WHERE binding_id=b.id;
 IF old.id IS NOT NULL THEN RETURN jsonb_build_object('schema_version','quest-d100-progress/1',
  'state','duplicate_ignored','receipt_id',old.id,'source_sha256',old.native_facts_sha256);END IF;
 INSERT INTO mission_factory_owner.c353_d100_rolls(id,binding_id,character_id,message_id,result,role)
 VALUES(extensions.uuid_generate_v5(p_message,'quest-d100-roll/1'),b.id,p_character,p_message,p_result,role_name)
 ON CONFLICT(binding_id,character_id) DO NOTHING;
 SELECT * INTO guide FROM mission_factory_owner.c353_d100_rolls WHERE binding_id=b.id AND role='guide';
 SELECT * INTO support FROM mission_factory_owner.c353_d100_rolls WHERE binding_id=b.id AND role='support';
 IF guide.id IS NULL OR (b.support_character_id IS NOT NULL AND support.id IS NULL)
 THEN RETURN jsonb_build_object('schema_version','quest-d100-progress/1','state','waiting_native_roles','binding_id',b.id);END IF;
 threshold:=mission_academy_owner.c353_effective_threshold_v1(ch.threshold,ch.support_threshold,support.result);
 ok:=guide.result<=threshold;fact:=CASE WHEN ok THEN ch.success_fact ELSE ch.complication_fact END;
 decision:=CASE WHEN ok THEN b.success_decision_key ELSE b.complication_decision_key END;
 facts:=jsonb_build_object('schema_version','quest-native-d100-facts/1','binding_id',b.id,'master_session_id',q.session_id,
  'quest_arc_id',q.arc_id,'quest_episode_id',q.episode_id,'quest_source_sha256',q.source_sha256,'plan_version_id',q.plan_version_id,
  'step_key',b.step_key,'run_control_version',b.run_control_version,'native_policy_sha256',b.native_policy_sha256,
  'guide_roll_id',guide.id,'guide_result',guide.result,'guide_message_id',guide.message_id,
  'support_roll_id',support.id,'support_result',support.result,'support_message_id',support.message_id,
  'base_threshold',ch.threshold,'support_threshold',ch.support_threshold,'effective_threshold',threshold,
  'success',ok,'native_fact_code',fact,'decision_key',decision);
 receipt_id:=extensions.uuid_generate_v5(b.id,'quest-native-d100-receipt/1');
 INSERT INTO mission_factory_owner.c353_d100_receipts(id,binding_id,guide_roll_id,support_roll_id,effective_threshold,
  success,native_fact_code,decision_key,native_facts,native_facts_sha256)
 VALUES(receipt_id,b.id,guide.id,support.id,threshold,ok,fact,decision,facts,mission_factory_owner.sha(facts));
 RETURN jsonb_build_object('schema_version','quest-d100-progress/1','state','resolved_receipt_available',
  'receipt_id',receipt_id,'source_sha256',mission_factory_owner.sha(facts),'success',ok,'decision_key',decision);
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c353_d100_receipt_assert_v1(p_session uuid, p_receipt uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q mission_factory_owner.quest_run_sources; b mission_factory_owner.c353_d100_bindings;
 rec mission_factory_owner.c353_d100_receipts; guide mission_factory_owner.c353_d100_rolls;
 support mission_factory_owner.c353_d100_rolls; ch mission_academy_owner.d100_challenges;
 policy mission_academy_owner.policies; expected integer; facts jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c353_d100_control WHERE singleton AND enabled)
 THEN RAISE EXCEPTION 'C353_D100_DISABLED' USING ERRCODE='42501';END IF;
 PERFORM mission_factory_owner.quest_run_source_assert_v1(p_session);
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 SELECT * INTO STRICT rec FROM mission_factory_owner.c353_d100_receipts WHERE id=p_receipt;
 SELECT * INTO STRICT b FROM mission_factory_owner.c353_d100_bindings WHERE id=rec.binding_id AND session_id=p_session;
 SELECT * INTO STRICT guide FROM mission_factory_owner.c353_d100_rolls WHERE id=rec.guide_roll_id
  AND binding_id=b.id AND role='guide' AND character_id=b.guide_character_id;
 IF b.support_character_id IS NOT NULL THEN SELECT * INTO STRICT support FROM mission_factory_owner.c353_d100_rolls
  WHERE id=rec.support_roll_id AND binding_id=b.id AND role='support' AND character_id=b.support_character_id;
 ELSIF rec.support_roll_id IS NOT NULL THEN RAISE EXCEPTION 'C353_D100_SUPPORT_DRIFT';END IF;
 SELECT * INTO STRICT ch FROM mission_academy_owner.d100_challenges WHERE mission_id=b.policy_mission_id AND step_key=b.policy_step_key AND active;
 SELECT * INTO STRICT policy FROM mission_academy_owner.policies WHERE mission_id=b.policy_mission_id AND active;
 expected:=mission_academy_owner.c353_effective_threshold_v1(ch.threshold,ch.support_threshold,support.result);
 facts:=jsonb_build_object('schema_version','quest-native-d100-facts/1','binding_id',b.id,'master_session_id',q.session_id,
  'quest_arc_id',q.arc_id,'quest_episode_id',q.episode_id,'quest_source_sha256',q.source_sha256,'plan_version_id',q.plan_version_id,
  'step_key',b.step_key,'run_control_version',b.run_control_version,'native_policy_sha256',b.native_policy_sha256,
  'guide_roll_id',guide.id,'guide_result',guide.result,'guide_message_id',guide.message_id,
  'support_roll_id',support.id,'support_result',support.result,'support_message_id',support.message_id,
  'base_threshold',ch.threshold,'support_threshold',ch.support_threshold,'effective_threshold',expected,
  'success',guide.result<=expected,'native_fact_code',CASE WHEN guide.result<=expected THEN ch.success_fact ELSE ch.complication_fact END,
  'decision_key',CASE WHEN guide.result<=expected THEN b.success_decision_key ELSE b.complication_decision_key END);
 IF b.quest_source_sha256<>q.source_sha256 OR b.plan_version_id<>q.plan_version_id OR b.definition_sha256<>q.definition_sha256
  OR b.native_policy_sha256<>mission_factory_owner.sha(jsonb_build_object('policy',to_jsonb(policy),'challenge',to_jsonb(ch)))
  OR rec.effective_threshold<>expected OR rec.success IS DISTINCT FROM (guide.result<=expected)
  OR rec.native_fact_code IS DISTINCT FROM (CASE WHEN rec.success THEN ch.success_fact ELSE ch.complication_fact END)
  OR rec.decision_key IS DISTINCT FROM (CASE WHEN rec.success THEN b.success_decision_key ELSE b.complication_decision_key END)
  OR rec.native_facts IS DISTINCT FROM facts OR rec.native_facts_sha256<>mission_factory_owner.sha(facts)
  OR NOT EXISTS(SELECT 1 FROM public.messages msg WHERE msg.id=guide.message_id AND msg.location_id=q.location_id
   AND msg.character_id=guide.character_id AND msg.kind='roll' AND msg.dice_sides=100 AND msg.dice_result=guide.result)
  OR (support.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.messages msg WHERE msg.id=support.message_id
   AND msg.location_id=q.location_id AND msg.character_id=support.character_id AND msg.kind='roll' AND msg.dice_sides=100 AND msg.dice_result=support.result))
 THEN RAISE EXCEPTION 'C353_D100_RECEIPT_DRIFT' USING ERRCODE='40001';END IF;
 RETURN jsonb_build_object('schema_version','quest-native-d100-receipt/1','receipt_id',rec.id,
  'source_sha256',rec.native_facts_sha256,'binding',to_jsonb(b),'native_facts',rec.native_facts,
  'transition_status','NOT_APPLIED_BY_D100_PRODUCER');
END $function$
